import math

def calculate_circle_area(radius):
    if radius < 0:
        return 0
    return math.pi * radius ** 2

test_cases = [5, 10, 3.5, -2]
for r in test_cases:
    print(f"Radius {r}: Area = {calculate_circle_area(r):.2f}")

def factorial(n):
    if n == 0 or n == 1:
        return 1
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

print(factorial(5))
print(factorial(3))

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

print(factorial(5))

def calculate_grade(score):
    if score >= 90:
        return 'A'
    elif score >= 80:
        return 'B'
    elif score >= 70:
        return 'C'
    elif score >= 60:
        return 'D'
    else:
        return 'F'

print(calculate_grade(95))
print(calculate_grade(82))
print(calculate_grade(65))
